"""Bind actual native results and prototype comparison to this cache revision."""
from pathlib import Path
import json,hashlib,shutil,copy
R=Path(__file__).resolve().parents[3];O=R/'art/source-to-3d/item-vault/v01';B=R/'build/item-vault-v01-native';N=O/'native-evidence';N.mkdir(exist_ok=True);ID='tech-priests-stone-cache-item-vault'
h=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
assert json.loads((O/'integration.json').read_text())['source_sha256']==h(O/'item-vault-v01.blend'),'Native evidence cannot bind stale integrated art'
binding=json.loads((B/'source-binding.json').read_text())
for p in (R/'tech-priests_src/graphics/entity/item-vault-v01').glob('*.png'):
 assert binding[p.relative_to(R/'tech-priests_src').as_posix()]==h(p),'Native art snapshot is stale'
assert binding['prototypes/martian_stone_cache.lua']==h(R/'tech-priests_src/prototypes/martian_stone_cache.lua')
before=json.loads((O/'contract.json').read_text());after=json.loads((B/'user-data/script-output/data-raw-dump.json').read_text());changes={}
baseline_path=R/'build/martian-cache-v01-native/user-data/script-output/data-raw-dump.json';assert h(baseline_path)==before['reconciliation']['baseline_dump_sha256'];baseline=json.loads(baseline_path.read_text());family=[]
for kind in ('container','accumulator','storage-tank','item','recipe'):
 for name,definition in baseline.get(kind,{}).items():
  if name==ID:continue
  if name.startswith('tech-priests-stone-cache-') or name in ('tech-priests-martian-stone-cache','tech-priests-basic-space-cargo-inventory','tech-priests-advanced-space-cargo-inventory'):
   if kind=='recipe' and name==ID+'-recycling':
    expected=copy.deepcopy(definition);expected['icons'][1]['icon']='__tech-priests__/graphics/entity/item-vault-v01/icon.png';assert after[kind][name]==expected,'Recycling gameplay changed beyond inherited item icon'
    continue
   assert after[kind][name]==definition,(kind,name,'unrelated family definition changed');family.append(kind+'/'+name)
(O/'family-preservation.json').write_text(json.dumps(dict(passed=True,unchanged_definitions=family,derived_recycling_recipe='Only the autogenerated Item Vault recycling icon inherits the new item icon; all its gameplay fields unchanged',baseline_dump_sha256=h(baseline_path),current_dump_sha256=h(B/'user-data/script-output/data-raw-dump.json')),indent=2)+'\n')
def diff(a,b,path=''):
 if type(a)!=type(b):return [path]
 if isinstance(a,dict):return [p for k in a.keys()|b.keys() for p in ([path+'/'+k] if k not in a or k not in b else diff(a[k],b[k],path+'/'+k))]
 if isinstance(a,list):return [path] if len(a)!=len(b) else [p for i,(x,y) in enumerate(zip(a,b)) for p in diff(x,y,path+'/'+str(i))]
 return [] if a==b else [path]
for label,kind in [('prototype','container'),('item','item'),('recipe','recipe')]:
 paths=diff(before[label],after[kind][ID]);changes[label]=paths
 allowed=lambda p:p in ('/icon','/icon_size') or p.startswith('/picture/') or (p.startswith('/circuit_connector/') and any('/sprites/'+field+'/' in p for field in ('connector_main','connector_shadow')))
 assert all(allowed(p) for p in paths),paths
native_dir=B/'user-data/script-output/item-vault'
for name in ('native-results.json','reload-results.json','native-plain.png','native-wired.png','native-ghost.png'):shutil.copy2(native_dir/name,N/name)
native=json.loads((N/'native-results.json').read_text());reload=json.loads((N/'reload-results.json').read_text());assert native['passed'] and reload['reload_preserved']
shutil.copy2(B/'source-binding.json',N/'source-binding.json')
receipt=dict(passed=True,source_sha256=h(O/'item-vault-v01.blend'),export_sha256=h(O/'item-vault-v01.glb'),prototype_changes=changes,native=native,reload=reload,art_hashes={p.name:h(p) for p in (R/'tech-priests_src/graphics/entity/item-vault-v01').glob('*.png')},owner_approval='Pending materials and revised model review; technical pass is not owner acceptance')
(N/'review.json').write_text(json.dumps(receipt,indent=2)+'\n');print('CURRENT_CACHE_NATIVE_EVIDENCE_SAVED')
